// Consolidated packets: several records printed into one PDF. Each record is
// read with its own patient, date and status, so an amendment later in the
// same file supersedes the preliminary value, exactly as across two files.
// Fixture: packet-synthetic.pdf (fictional; generated by reportlab):
//   p1 preliminary, TV-P2001, collected 05 Nov: ferritin 4
//   p2 draft note, no header, "ferritin 4 ng/mL" in prose
//   p3 amended, TV-P2001, same collection: ferritin 40, plus an instruction
//      line and a "version used | 05 Nov ..." row that are not results
//   p4 a different person with the same printed name, TV-P2002
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parseBuffer } from "../ingest/parse.mjs";
import { shutdownOcr } from "../ingest/ocr.mjs";
import {
  packetSegments,
  extractSegment,
  extractReport,
  reportMeta,
  subjectOf,
} from "./observations.mjs";
import { createLocalServer } from "../src/server.mjs";

process.env.VM_COUNTERS_ALLOW_FILE = "on";
const BYTES = readFileSync(
  new URL("./fixtures/files/packet-synthetic.pdf", import.meta.url),
);
let doc;
test.before(async () => {
  ({ doc } = await parseBuffer(BYTES, "packet-synthetic.pdf"));
});
test.after(() => shutdownOcr());

test("a stacked header row is read by column, and a name is never an ID", () => {
  const m = reportMeta(
    "PATIENT NAME PATIENT ID\n\nAsha Rao TV-P2001\n\nSAMPLE COLLECTED REPORT ISSUED\n\n05 Nov 2026 09:00 05 Nov 2026 12:00",
  );
  assert.equal(m.patient.id, "TV-P2001");
  assert.equal(m.patient.name, "Asha Rao");
  assert.equal(m.collected, "2026-11-05");
  assert.equal(m.reported, "2026-11-05");
  // Before: "PATIENT ID\n\nAsha" was read as the ID "ASHA".
  const bare = reportMeta(
    "PATIENT NAME PATIENT ID\n\nAsha Rao\n\nFerritin 4 ng/mL 15 - 150",
  );
  assert.notEqual(bare.patient?.id, "ASHA");
  // Two identifiers in one value row: the one under PATIENT ID.
  const two = reportMeta(
    "PATIENT / ENCOUNTER PATIENT ID\n\nAsha Rao / ENC-0042 TV-P2001",
  );
  assert.equal(two.patient.id, "TV-P2001");
});

test("a status label in the header counts; the same word in prose does not", () => {
  assert.equal(
    reportMeta("# LAB RESULT\n\nAMENDED / FINAL CORRECTED VERSION").status,
    "amended",
  );
  assert.equal(
    reportMeta("# LAB RESULT\n\nPRELIMINARY CHEMISTRY").status,
    "preliminary",
  );
  assert.equal(
    reportMeta(
      "# LAB RESULT\n\nCHEMISTRY\n\nPANEL\n\nNOTES\n\nThis was superseded by the amended version.",
    ).status,
    "unknown",
  );
});

test("the packet splits into its records, each with its own header", () => {
  const segs = packetSegments(doc);
  assert.deepEqual(
    segs.map((s) => s.pages),
    [[1], [2], [3], [4]],
  );
  const reps = segs.map((s) => extractSegment(doc, s));
  assert.deepEqual(
    reps.map((r) => [
      r.meta.patient?.id ?? null,
      r.meta.collected,
      r.meta.status,
    ]),
    [
      ["TV-P2001", "2026-11-05", "preliminary"],
      [null, null, "unknown"],
      ["TV-P2001", "2026-11-05", "amended"],
      ["TV-P2002", "2026-11-02", "final"],
    ],
  );
  // offsets still point into the original text
  const o = reps[2].observations.find((x) => x.test === "Ferritin");
  assert.equal(
    doc.text.slice(o.source.start, o.source.end).includes("40"),
    true,
  );
  // an instruction line and a day-of-month row are not results
  assert.deepEqual(
    reps[2].observations.map((x) => `${x.test}=${x.raw}`),
    ["Ferritin=40", "Hemoglobin=11.2"],
  );
  // the headerless draft note is its own subject, never the patient's
  assert.equal(subjectOf({ ...reps[1], sourceId: "s", segment: 2 }), "doc:s#2");
});

test("a single report is never split", async () => {
  for (const f of ["a-2026-10-amended.pdf", "a-2026-09.pdf"]) {
    const { doc: d } = await parseBuffer(
      readFileSync(new URL("./fixtures/files/" + f, import.meta.url)),
      f,
    );
    assert.equal(packetSegments(d), null, f);
    assert.ok(extractReport(d).observations.length > 0);
  }
});

test("asked through a workspace: the amendment wins, the other patient stays separate", async () => {
  const srv = createLocalServer({ port: 0 });
  await new Promise((r) => srv.listen(0, "127.0.0.1", r));
  const base = `http://127.0.0.1:${srv.address().port}/api/public`;
  try {
    const ws = await (
      await fetch(base + "/workspace", { method: "POST" })
    ).json();
    const up = await fetch(`${base}/workspace/${ws.id}/upload`, {
      method: "POST",
      headers: {
        "x-file-name": "packet.pdf",
        "content-type": "application/octet-stream",
      },
      body: BYTES,
    });
    assert.equal(up.status, 202);
    for (let i = 0; i < 200; i++) {
      const st = await (await fetch(`${base}/workspace/${ws.id}`)).json();
      if (
        st.ready &&
        st.documents.every((d) => ["ready", "needs_review"].includes(d.status))
      )
        break;
      await new Promise((r) => setTimeout(r, 50));
    }
    const ask = async (question) =>
      (
        await (
          await fetch(base + "/ask", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ case: ws.id, question }),
          })
        ).json()
      ).lead?.text ?? "";
    const askP = async (question, patient) =>
      (
        await (
          await fetch(base + "/ask", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ case: ws.id, question, patient }),
          })
        ).json()
      ).lead?.text ?? "";
    const named = await ask("What is TV-P2001's ferritin?");
    assert.match(named, /\b40 ng\/mL/);
    assert.doesNotMatch(named, /result is 4 ng/);
    assert.match(
      await ask("What was TV-P2001's ferritin before the correction?"),
      /\b4 ng\/mL[\s\S]*40/,
    );
    // two people share the printed name, one of them on a single misfiled
    // page: without explicit context an unnamed question is ambiguous and
    // asks whose results; it never answers for a count-picked person.
    const unnamed = await ask("What is my ferritin?");
    assert.match(unnamed, /Whose results should I look at\?/);
    assert.doesNotMatch(unnamed, /result is \d+ ng/);
    // with the patient selected on screen (validated explicit context) the
    // same question answers for them, names the namesake it left out, and
    // uses the amended value - never the namesake's, never the superseded.
    const selected = await askP("What is my ferritin?", "TV-P2001");
    assert.match(selected, /\b40 ng\/mL/);
    assert.match(selected, /TV-P2001[\s\S]*TV-P2002/);
    assert.doesNotMatch(selected, /result is (4|90) ng/);
    // a mismatched selection (not a subject of these records) selects
    // nothing: the question stays ambiguous.
    // Both cache request orders and transitions: ownership must survive
    // replay, not just the text. Same document, distinct patient rows.
    for (const q of ["What is my ferritin?", "What is the ferritin result?"]) {
      for (const patient of [
        "TV-P2002",
        "TV-P2001",
        null,
        "TV-P2001",
        "TV-P2002",
        "TV-P9999",
        null,
      ]) {
        const res = await fetch(base + "/ask", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ case: ws.id, question: q, patient }),
        });
        const a = await res.json();
        if (patient === "TV-P2001" || patient === "TV-P2002") {
          const value = patient === "TV-P2001" ? "40" : "90";
          assert.match(a.final.text, new RegExp(value + " ng/mL"));
          assert.match(a.final.text, new RegExp(patient));
          assert.ok(
            a.final.citations.some((c) => c.quote.includes(value)),
            "chosen value cited",
          );
          assert.ok(
            !a.final.citations.some((c) =>
              c.quote.includes(patient === "TV-P2001" ? "90" : "40"),
            ),
            "no other patient's value cited",
          );
        } else {
          assert.equal(a.final.verdict, "AMBIGUOUS_PATIENT");
          assert.deepEqual(a.final.citations, []);
        }
      }
    }
    const mismatched = await askP("What is my ferritin?", "TV-P9999");
    assert.match(mismatched, /Whose results should I look at\?/);
  } finally {
    await new Promise((r) => srv.close(r));
  }
});
